  ui_story_32290401_94_dialog_content = "Sepertinya mereka telah menghabiskan banyak sumber daya untuk mengembangkan permainan ini. Ini sama bagusnya dengan Monstervania... Yang berarti ini akan laku keras sama seperti itu!",
  ui_story_32290401_95_dialog_content = "Saya pikir video game bisa mencerminkan beberapa bagian dari realitas kita.",
